BEGIN;
DO $test$
DECLARE buyer jsonb:=jsonb_build_object('system','office','subject_id',test_uuid(13001),'store_id',test_uuid(101),'can_manage',true,'can_create',true,'can_office_approve',true,'can_view_prices',true);
 r jsonb;original_payload jsonb;original_result jsonb;payload jsonb;page jsonb;report jsonb;rid uuid;lid uuid;qid uuid;poid uuid;polid uuid;receipt_id uuid:=test_uuid(13002);path text;stock numeric;original_po uuid;original_line uuid;next_rid uuid;
BEGIN
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 ASSERT NOT EXISTS(SELECT 1 FROM public.test_procurement_two_stage_upgrade u WHERE public.procurement_order_snapshot(test_uuid(101),u.purchase_order_id,buyer) IS DISTINCT FROM u.snapshot),'Existing Office accounting snapshots preserved';
 SELECT to_jsonb(p) INTO r FROM public.procurement_store_policies p WHERE restaurant_id=test_uuid(101);
 PERFORM public.procurement_command(test_uuid(101),'configure',NULL,(r->>'row_version')::integer,'two-stage-config','{"enabled":true,"new_requests_enabled":true,"high_value_amount":1,"max_price_increase_percent":20,"quantity_review_multiplier":100}',buyer);
 UPDATE public.inventory_supplier_items SET order_unit='g',order_unit_quantity_base=1,min_order_quantity=1,unit_price=100 WHERE id=test_uuid(401);
 UPDATE public.inventory_products SET product_code='RAW-001' WHERE id=test_uuid(301);
 ASSERT NOT EXISTS(SELECT 1 FROM public.test_procurement_two_stage_upgrade u JOIN public.inventory_purchase_requests r ON r.id=u.request_id WHERE r.approval_hash IS DISTINCT FROM u.approval_hash), 'Existing approvals preserved';
 ASSERT NOT EXISTS(SELECT 1 FROM public.test_procurement_two_stage_upgrade u WHERE public.procurement_request_hash(u.request_id) IS DISTINCT FROM u.approval_hash), 'Added display fields preserve approval hashes';
 PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claim.sub',test_uuid(1)::text,true);
 payload:=jsonb_build_object('reason','Two-stage test','requested_delivery_date',current_date+2,'lines',jsonb_build_array(jsonb_build_object('product_id',test_uuid(301),'quantity',10,'unit','g')));
 r:=public.procurement_command(test_uuid(101),'create_request',NULL,0,'two-stage-create',payload);rid:=(r->>'id')::uuid;
 ASSERT r->>'approval_policy_version'='3';
 SELECT id INTO lid FROM public.inventory_purchase_request_lines WHERE request_id=rid AND active;
 ASSERT (SELECT product_code_snapshot FROM public.inventory_purchase_request_lines WHERE id=lid)='RAW-001';
 ASSERT public.procurement_command(test_uuid(101),'create_request',NULL,0,'two-stage-create',payload)=r;
 page:=public.procurement_workspace_page(test_uuid(101),'{"catalog_only":true,"catalog_search":"RAW-001"}');
 ASSERT jsonb_array_length(page->'products')=1 AND NOT(page ? 'requests'), 'Search matches code and avoids unrelated pages';
 r:=public.procurement_command(test_uuid(101),'submit_request',rid,1,'two-stage-submit');
 PERFORM public.test_expect_error(format('SELECT public.procurement_command(%L,%L,%L,2,%L,%L::jsonb)',test_uuid(101),'store_approve',rid,'two-stage-self','{}'),'PROCUREMENT_SELF_APPROVAL_FORBIDDEN');
 PERFORM set_config('request.jwt.claim.sub',test_uuid(2)::text,true);
 r:=public.procurement_command(test_uuid(101),'store_approve',rid,2,'two-stage-store');ASSERT r->>'status'='office_review';
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 PERFORM public.test_expect_error(format('SELECT public.procurement_command(%L,%L,%L,3,%L,%L::jsonb,%L::jsonb)',test_uuid(101),'brand_approve',rid,'two-stage-bm','{}',buyer),'PROCUREMENT_APPROVAL_STAGE_REMOVED');
 r:=public.procurement_command(test_uuid(101),'save_quote',rid,3,'two-stage-quote',jsonb_build_object('supplier_id',test_uuid(201),'valid_until',current_date+2,'delivery_date',current_date+2,'payment_terms','Net 7','evidence_reference','Written quote','lines',jsonb_build_array(jsonb_build_object('request_line_id',lid,'supplier_item_id',test_uuid(401),'quantity_base',10,'unit_price',100,'tax_rate',0))),buyer);
 SELECT id INTO qid FROM public.procurement_quotes WHERE request_id=rid;
 r:=public.procurement_command(test_uuid(101),'select_quote',rid,4,'two-stage-select',jsonb_build_object('quote_id',qid,'reason','Selected'),buyer);
 r:=public.procurement_command(test_uuid(101),'office_approve',rid,5,'two-stage-approve','{}',buyer);
 ASSERT r->>'status'='approved','Buyer is final approver even above the configured threshold';
 r:=public.procurement_command(test_uuid(101),'issue_po',rid,6,'two-stage-issue',jsonb_build_object('quote_id',qid,'delivery_address','Store','contact_name','Receiver'),buyer);poid:=(r->'purchase_order'->>'id')::uuid;
 original_po:=poid;SELECT id INTO polid FROM public.inventory_purchase_order_lines WHERE purchase_order_id=poid;original_line:=polid;
 PERFORM set_config('app.procurement_write','true',true);
 UPDATE public.inventory_purchase_orders SET procurement_status='confirmed' WHERE id=poid;
 PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claim.sub',test_uuid(1)::text,true);
 path:=test_uuid(101)::text||'/'||receipt_id::text||'/statement.pdf';
 INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('inventory-receipt-statements',path,test_uuid(1)::text,'{"mimetype":"application/pdf","size":100}');
 SELECT current_stock INTO stock FROM public.inventory_items WHERE id=test_uuid(501);
 SELECT to_jsonb(po) INTO r FROM public.inventory_purchase_orders po WHERE id=poid;
 payload:=jsonb_build_object('p_purchase_order_id',poid,'p_receipt_id',receipt_id,'p_expected_order_version',r->'row_version','p_expected_receipt_version',0,'p_idempotency_key','two-stage-receive','p_inspector_name','Actual receiver','p_statement_storage_path',path,'p_lines',jsonb_build_array(jsonb_build_object('purchase_order_line_id',polid,'received_quantity_base',7,'discrepancy_reason','Short 3','inspection',jsonb_build_object('spec_ok',true,'quality_ok',true,'packaging_ok',true,'expiry_not_applicable',true,'issue_type','shortage','photo_paths','[]'::jsonb))));
 r:=public.finalize_procurement_receipt(payload);original_payload:=payload;original_result:=r;
 ASSERT (SELECT current_stock FROM public.inventory_items WHERE id=test_uuid(501))=stock+7;
 ASSERT public.finalize_procurement_receipt(payload)=r;
 ASSERT (SELECT current_stock FROM public.inventory_items WHERE id=test_uuid(501))=stock+7,'Retry does not repost stock';
 report:=public.procurement_receipt_report_data(test_uuid(101),receipt_id);
 ASSERT report->>'kind'='discrepancy';ASSERT report->'data'->'lines'->0->>'product_code'='RAW-001';
 ASSERT NOT(report->'data'->'lines'->0 ? 'unit_price');
 page:=public.procurement_shortages(test_uuid(101));ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(page->'rows') x WHERE x->>'original_order_line_id'=polid::text AND (x->>'shortage_quantity_base')::numeric=3);
 payload:=jsonb_build_object('reason','Carry previous shortage','requested_delivery_date',current_date+2,'lines',jsonb_build_array(jsonb_build_object('product_id',test_uuid(301),'quantity',3,'unit','g','preferred_supplier_id',test_uuid(201),'shortage_sources',jsonb_build_array(jsonb_build_object('original_order_line_id',polid,'quantity_base',3)))));
 r:=public.procurement_command(test_uuid(101),'create_request',NULL,0,'carry-create',payload);next_rid:=(r->>'id')::uuid;
 PERFORM public.test_expect_error(format('SELECT public.procurement_command(%L,%L,NULL,0,%L,%L::jsonb)',test_uuid(101),'create_request','carry-duplicate',payload),'PROCUREMENT_SHORTAGE_CHANGED');
 page:=public.procurement_workspace_page(test_uuid(101),jsonb_build_object('request_id',next_rid));ASSERT jsonb_array_length(page->'request_detail'->'lines'->0->'shortage_sources')=1;
 receipt_id:=test_uuid(13005);path:=test_uuid(101)::text||'/'||receipt_id::text||'/statement.pdf';
 INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('inventory-receipt-statements',path,test_uuid(1)::text,'{"mimetype":"application/pdf","size":100}');
 SELECT to_jsonb(po) INTO r FROM public.inventory_purchase_orders po WHERE id=original_po;
 payload:=jsonb_build_object('p_purchase_order_id',original_po,'p_receipt_id',receipt_id,'p_expected_order_version',r->'row_version','p_expected_receipt_version',0,'p_idempotency_key','original-late-receive','p_inspector_name','Actual receiver','p_statement_storage_path',path,'p_lines',jsonb_build_array(jsonb_build_object('purchase_order_line_id',original_line,'received_quantity_base',1,'discrepancy_reason','Still short 2','inspection',jsonb_build_object('spec_ok',true,'quality_ok',true,'packaging_ok',true,'expiry_not_applicable',true,'issue_type','shortage','photo_paths','[]'::jsonb))));
 r:=public.finalize_procurement_receipt(payload);
 PERFORM public.test_expect_error(format('SELECT public.procurement_command(%L,%L,%L,1,%L,%L::jsonb)',test_uuid(101),'submit_request',next_rid,'carry-stale-submit','{}'),'PROCUREMENT_SHORTAGE_CHANGED');
 page:=public.procurement_shortages(test_uuid(101),jsonb_build_object('request_id',next_rid,'owned_shortages_only',true));
 ASSERT (page->'rows'->0->>'shortage_quantity_base')::numeric=2,'Owned shortage refresh includes new actual delivery';
 payload:=jsonb_build_object('reason','Carry shortage plus 2 new units','requested_delivery_date',current_date+2,'lines',jsonb_build_array(jsonb_build_object('product_id',test_uuid(301),'quantity',4,'unit','g','preferred_supplier_id',test_uuid(201),'shortage_sources',jsonb_build_array(jsonb_build_object('original_order_line_id',original_line,'quantity_base',2)))));
 r:=public.procurement_command(test_uuid(101),'save_request',next_rid,1,'carry-refresh',payload);
 ASSERT r->>'row_version'='2';

 SELECT id INTO lid FROM public.inventory_purchase_request_lines WHERE request_id=next_rid AND active;
 r:=public.procurement_command(test_uuid(101),'submit_request',next_rid,2,'carry-submit');
 PERFORM set_config('request.jwt.claim.sub',test_uuid(2)::text,true);r:=public.procurement_command(test_uuid(101),'store_approve',next_rid,3,'carry-store');
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 r:=public.procurement_command(test_uuid(101),'save_quote',next_rid,4,'carry-quote',jsonb_build_object('supplier_id',test_uuid(201),'valid_until',current_date+2,'delivery_date',current_date+2,'payment_terms','Net 7','evidence_reference','Written quote','lines',jsonb_build_array(jsonb_build_object('request_line_id',lid,'supplier_item_id',test_uuid(401),'quantity_base',4,'unit_price',100,'tax_rate',0))),buyer);
 SELECT id INTO qid FROM public.procurement_quotes WHERE request_id=next_rid;
 r:=public.procurement_command(test_uuid(101),'select_quote',next_rid,5,'carry-select',jsonb_build_object('quote_id',qid,'reason','Selected'),buyer);
 r:=public.procurement_command(test_uuid(101),'office_approve',next_rid,6,'carry-approve','{}',buyer);
 r:=public.procurement_command(test_uuid(101),'issue_po',next_rid,7,'carry-issue',jsonb_build_object('quote_id',qid,'delivery_address','Store','contact_name','Receiver'),buyer);poid:=(r->'purchase_order'->>'id')::uuid;
 ASSERT (SELECT transferred_quantity_base FROM public.inventory_purchase_order_lines WHERE id=original_line)=2;
 ASSERT (SELECT commercial_terms->>'receiving_outcome' FROM public.inventory_purchase_orders WHERE id=original_po)='partial_transferred';
 ASSERT (SELECT current_stock FROM public.inventory_items WHERE id=test_uuid(501))=stock+8,'PO issuance never increases stock';
 ASSERT (SELECT count(*) FROM public.procurement_shortage_allocations WHERE original_order_line_id=original_line AND status='issued')=1;
 ASSERT public.procurement_receipt_report_data(test_uuid(101),test_uuid(13002),buyer)=report,'Original discrepancy snapshot remains immutable';
 PERFORM set_config('app.procurement_write','true',true);UPDATE public.inventory_purchase_orders SET procurement_status='confirmed' WHERE id=poid;
 SELECT id INTO polid FROM public.inventory_purchase_order_lines WHERE purchase_order_id=poid;
 PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claim.sub',test_uuid(1)::text,true);
 receipt_id:=test_uuid(13003);path:=test_uuid(101)::text||'/'||receipt_id::text||'/statement.pdf';
 INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('inventory-receipt-statements',path,test_uuid(1)::text,'{"mimetype":"application/pdf","size":100}');
 SELECT to_jsonb(po) INTO r FROM public.inventory_purchase_orders po WHERE id=poid;
 payload:=jsonb_build_object('p_purchase_order_id',poid,'p_receipt_id',receipt_id,'p_expected_order_version',r->'row_version','p_expected_receipt_version',0,'p_idempotency_key','carry-zero-receive','p_inspector_name','Actual receiver','p_statement_storage_path',path,'p_lines',jsonb_build_array(jsonb_build_object('purchase_order_line_id',polid,'received_quantity_base',0,'discrepancy_reason','Nothing delivered','inspection',jsonb_build_object('issue_type','shortage','photo_paths','[]'::jsonb))));
 r:=public.finalize_procurement_receipt(payload);ASSERT (SELECT current_stock FROM public.inventory_items WHERE id=test_uuid(501))=stock+8;
 ASSERT r->'report'->>'kind'='discrepancy','Zero delivery is recorded without stock';
 receipt_id:=test_uuid(13004);path:=test_uuid(101)::text||'/'||receipt_id::text||'/statement.pdf';
 INSERT INTO storage.objects(bucket_id,name,owner_id,metadata) VALUES('inventory-receipt-statements',path,test_uuid(1)::text,'{"mimetype":"application/pdf","size":100}');
 payload:=payload||jsonb_build_object('p_receipt_id',receipt_id,'p_expected_order_version',r->'purchase_order'->'row_version','p_idempotency_key','carry-complete-receive','p_statement_storage_path',path,'p_lines',jsonb_build_array(jsonb_build_object('purchase_order_line_id',polid,'received_quantity_base',4,'inspection',jsonb_build_object('spec_ok',true,'quality_ok',true,'packaging_ok',true,'expiry_not_applicable',true,'issue_type','none','photo_paths','[]'::jsonb))));
 r:=public.finalize_procurement_receipt(payload);ASSERT r->'report'->>'kind'='complete';
 ASSERT (SELECT current_stock FROM public.inventory_items WHERE id=test_uuid(501))=stock+12;
 ASSERT public.finalize_procurement_receipt(payload)=r,'Complete receipt replay is stable';
 ASSERT public.finalize_procurement_receipt(original_payload)=original_result,'Original receipt replay stays stable after later PO/receiving changes';
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.procurement_shortages(test_uuid(101))->'rows') x WHERE x->>'original_order_line_id' IN(original_line::text,polid::text));

 PERFORM set_config('request.jwt.claim.role','authenticated',true);PERFORM set_config('request.jwt.claim.sub',test_uuid(1)::text,true);
 PERFORM public.test_expect_error(format('SELECT public.procurement_receipt_report_data(%L,%L)',test_uuid(102),receipt_id),'PROCUREMENT_SCOPE_FORBIDDEN');
 RAISE NOTICE 'PASS: two-stage approval, code search/snapshot, atomic partial receipt/retry, immutable price-free report, reservation conflict, shortage PO transfer and tenant isolation';
END $test$;
ROLLBACK;
